<?php
require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../includes/database.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/exam_paper_page.php';
Auth::requireRole(['super_admin','school_admin','teacher']);Auth::requireAccess('exam_specification_grids');
$db=getDB();$actor=learningActor($db,(int)Auth::getUserId(),(int)Auth::getSchoolId(),Auth::isReadOnly());$class=(int)($_POST['class_id']??$_GET['class_id']??0);$subject=(int)($_POST['subject_id']??$_GET['subject_id']??0);$error='';$editing=null;$initialConfig=[];$gridName='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{$action=$_POST['action']??'';if(!is_string($action)||!in_array($action,['save','archive','restore'],true))throw new InvalidArgumentException('Choose one grid action.');
        $id=empty($_POST['grid_id'])?null:learningId($_POST['grid_id']);
        if($action==='save'){$name=$_POST['name']??'';if(!is_string($name))throw new InvalidArgumentException('Enter a valid grid name.');$initialConfig=examGridInputJson($_POST['config_json']??null);$id=examSaveGrid($db,$actor,$class,$subject,$name,$initialConfig,$id,$id?learningId($_POST['revision']??null):null);}
        else{if(!$id)throw new InvalidArgumentException('Choose an exam grid.');examArchiveGrid($db,$actor,$id,$action==='archive');}
        redirect(schoolRouteUrl('modules/learning/exam_specification_grids.php') . '?'.http_build_query(['class_id'=>$class,'subject_id'=>$subject]),'Exam grid saved successfully.','success');
    }catch(InvalidArgumentException $e){http_response_code(422);$error=$e->getMessage();$gridName=is_string($_POST['name']??null)?$_POST['name']:'';if(!empty($_POST['grid_id'])){try{$editing=examGridRecord($db,$actor,(int)$_POST['grid_id'],true);}catch(InvalidArgumentException $ignore){}}}
    catch(Throwable $e){http_response_code(500);$error=schoolPublicError($e);}
}
if($_SERVER['REQUEST_METHOD']==='GET'&&(isset($_GET['edit_grid_id'])||isset($_GET['load_grid_id']))){
    try{$record=examGridRecord($db,$actor,learningId($_GET['edit_grid_id']??$_GET['load_grid_id']));$class=$record['local_class_id'];$subject=$record['local_subject_id'];$initialConfig=examGridInputJson($record['config_json']);$gridName=$record['name'];
        if(isset($_GET['edit_grid_id'])){if(!$record['can_edit'])throw new InvalidArgumentException('Only the grid creator may edit it. Load a copy instead.');$editing=$record;}else $gridName.=' — copy';
    }catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}
}
[$classes,$subjectsByClass]=examPageSelectors($db,$actor);try{[$chapters,$topicsByChapter,$savedGrids,$referenceGrids]=examPageCatalog($db,$actor,$class,$subject);}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}
$archivedGrids=$subject?examGridList($db,$actor,$class,$subject,true):[];$canSave=$subject&&!$actor['read_only']&&learningCanCreate($db,$actor,$class,$subject);
$pageTitle='Exam Paper Grids';$activePage='exam_specification_grids';ob_start(); ?>
<div class="d-flex flex-wrap justify-content-between mb-3 gap-2"><div><h2>Exam Paper Grids</h2><p class="text-muted">Separate chapter-wise exam blueprints, not the normal paper grids.</p></div><a class="btn btn-outline-primary align-self-start" href="<?= schoolRouteUrl('modules/learning/exam_paper_generator.php') ?>?<?= http_build_query(['class_id'=>$class,'subject_id'=>$subject]) ?>">Exam Paper Generator</a></div>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= sanitize($error) ?></div><?php endif; ?>
<?php examSelectorForm($classes,$subjectsByClass,$class,$subject); ?>
<?php if($subject): ?>
<div class="card card-body mb-3"><h3 class="h5">Saved Exam Grids</h3><?php if(!$savedGrids): ?><p class="text-muted">No saved exam grid for this class subject.</p><?php endif; ?><?php foreach($savedGrids as $g): ?><div class="d-flex flex-wrap gap-2 justify-content-between border-bottom py-2"><span><?= sanitize($g['name']) ?><?= (int)$g['school_id']===0?' — shared default':'' ?></span><div><a class="btn btn-sm btn-outline-primary" href="?load_grid_id=<?= $g['id'] ?>">Load a copy</a><a class="btn btn-sm btn-outline-success" href="<?= schoolRouteUrl('modules/learning/exam_paper_generator.php') ?>?grid_id=<?= $g['id'] ?>">Generate</a><?php if($g['can_edit']): ?><a class="btn btn-sm btn-outline-secondary" href="?edit_grid_id=<?= $g['id'] ?>">Edit</a><form method="post" class="d-inline" data-erp-submit="learning-exam-specification-grids-action-0" data-erp-submit-args="<?= schoolPageActionArgs("learning-exam-specification-grids",[]) ?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="grid_id" value="<?= $g['id'] ?>"><input type="hidden" name="class_id" value="<?= $class ?>"><input type="hidden" name="subject_id" value="<?= $subject ?>"><button class="btn btn-sm btn-outline-danger">Archive</button></form><?php endif; ?></div></div><?php endforeach; ?></div>
<?php if($canSave): ?><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="class_id" value="<?= $class ?>"><input type="hidden" name="subject_id" value="<?= $subject ?>"><?php if($editing): ?><input type="hidden" name="grid_id" value="<?= $editing['id'] ?>"><input type="hidden" name="revision" value="<?= $editing['revision'] ?>"><?php endif; ?><label class="form-label">Grid name</label><input name="name" value="<?= sanitize($gridName) ?>" maxlength="200" required class="form-control mb-3" placeholder="e.g. First Term Mathematics — 75 marks"><?php include __DIR__.'/../../includes/exam_grid_editor.php'; ?><button class="btn btn-success mb-4"><?= $editing?'Save grid revision':'Save new Exam Grid' ?></button></form><?php endif; ?>
<?php if($archivedGrids): ?><details class="card card-body"><summary>My archived exam grids</summary><?php foreach($archivedGrids as $g): ?><form method="post" class="d-flex gap-2 align-items-center mt-2"><input type="hidden" name="action" value="restore"><input type="hidden" name="grid_id" value="<?= $g['id'] ?>"><input type="hidden" name="class_id" value="<?= $class ?>"><input type="hidden" name="subject_id" value="<?= $subject ?>"><span><?= sanitize($g['name']) ?></span><button class="btn btn-sm btn-outline-primary">Restore</button></form><?php endforeach; ?></details><?php endif; endif; ?>
<?php $content=ob_get_clean();include __DIR__.'/../../includes/header.php'; ?>
